/** @param {NS} ns */
export async function main(ns) {
  const servers = ns.scan('home');
  let best = null, bestChance = 0;
  for (const s of servers) {
    if (ns.hasRootAccess(s)) {
      const chance = ns.getServerRequiredHackingLevel(s) <= ns.getHackingLevel() ? ns.getServerSecurityLevel(s) : 0;
      if (chance > bestChance) {
        bestChance = chance;
        best = s;
      }
    }
  }
  if (best) {
    ns.tprint(`Hacking: ${best}`);
    await ns.hack(best);
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const servers = ['n00dles', 'foodnstuff', 'sigma-cosmetics', 'joesguns', '港'];
  let best = null;
  let bestChance = 0;
  for (const srv of servers) {
    if (ns.hasRootAccess(srv)) {
      const chance = ns.hackAnalyzeChance(srv);
      if (chance > bestChance) {
        bestChance = chance;
        best = srv;
      }
    }
  }
  if (best) {
    await ns.hack(best);
    ns.tprint(`Hacked ${best} with ${(bestChance * 100).toFixed(1)}% chance`);
  }
}
